// ===== SETTINGS (edit your details here) =====
const CONFIG = {
    upiId: 'yourname@upi',          // CHANGE: your parlour's UPI ID
    payeeName: 'Relax Zone Makeover',
    countryCode: '91',
    loyaltyDays: 30,                // return-visit offer window (days)
    adminPin: '1234',               // CHANGE: Admin PIN
    // WhatsApp Cloud API (Meta) — for AUTOMATIC message sending (no manual
    // tap-to-send needed). Leave these blank here; set the real values from
    // Admin Panel > WhatsApp API once you have them — they're saved to this
    // browser, same as the UPI ID above. Get these from
    // developers.facebook.com > your WhatsApp Business app > API Setup:
    //  - phoneNumberId: the "Phone number ID" shown there (NOT your actual phone number)
    //  - accessToken: a permanent access token for that app (temporary tokens expire in 24h)
    whatsappApiPhoneNumberId: '',
    whatsappApiAccessToken: '',
    whatsappApiVersion: 'v20.0'
};
const RZM_LOGO_DATA = 'data:image/jpeg;base64,';
const DEFAULT_SERVICES = [
    { name: 'Facial', items: [{n:'Fruit Facial',p:800},{n:'Gold Facial',p:1500},{n:'Diamond Facial',p:2000},{n:'Clean-up',p:500}] },
    { name: 'Hair', items: [{n:'Haircut',p:300},{n:'Hair Spa',p:1200},{n:'Hair Colour',p:1500}] },
    { name: 'Waxing & Threading', items: [{n:'Full Arms Wax',p:300},{n:'Full Legs Wax',p:500},{n:'Eyebrow',p:50},{n:'Upper Lip',p:30}] },
    { name: 'Nails', items: [{n:'Manicure',p:500},{n:'Pedicure',p:600}] },
    { name: 'Makeup', items: [{n:'Party Makeup',p:2500},{n:'Bridal Makeup',p:8000}] }
];
let services = JSON.parse(localStorage.getItem('rzm_services') || 'null') || DEFAULT_SERVICES;
services = services.map(c => ({ ...c, items: (c.items || []).map(s => ({ ...s, normalPrice: Number.isFinite(+s.normalPrice) ? +s.normalPrice : (+s.p || 0), primePrice: Number.isFinite(+s.primePrice) ? +s.primePrice : (+s.p || 0) })) }));
const saveServices = () => localStorage.setItem('rzm_services', JSON.stringify(services));
let currentPricingTier = 'Normal';
const priceFor = s => currentPricingTier === 'Prime' ? (+s.primePrice || 0) : (+s.normalPrice || 0);

let cart = [], totalAmount = 0, current = null, pdfDoc = null;
const $ = id => document.getElementById(id);
const esc = t => String(t).replace(/[&<>"']/g, c => ({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const db = () => JSON.parse(localStorage.getItem('rzm_customers') || '{}');
// ===== Return-visit discount =====
// A bill today starts a 30-day timer. If the customer comes back before it ends they get the
// admin-set % off, and the new bill restarts the timer from scratch. If they don't, it simply lapses.
const fmtPct = n => String(+(+n || 0).toFixed(2));
const getLoyaltyPct = () => {
    const v = localStorage.getItem('rzm_loyalty_pct');
    const n = v === null ? 5 : parseFloat(v);
    return Number.isFinite(n) ? Math.min(100, Math.max(0, n)) : 5;
};
const getLoyaltyDays = () => {
    const v = parseInt(localStorage.getItem('rzm_loyalty_days'), 10);
    return Number.isFinite(v) && v > 0 ? Math.min(365, v) : (CONFIG.loyaltyDays || 30);
};
const fmtDate = ts => new Date(ts).toLocaleDateString('en-IN');
function offerEndFor(ts) {            // offer runs through the end of the day, N days after the bill
    const d = new Date(ts); d.setDate(d.getDate() + getLoyaltyDays()); d.setHours(23, 59, 59, 999); return d.getTime();
}
function visitTs(v) {
    if (!v) return 0;
    if (v.ts) return +v.ts;
    const p = String(v.date || '').split('/').map(Number);   // old bills only have dd/mm/yyyy
    return p.length === 3 && p[0] ? new Date(p[2], p[1] - 1, p[0], 12).getTime() : 0;
}
// What does this customer get right now? {state:'none'|'active'|'expired', pct, until, from}
function getReturnOffer(phone) {
    const c = phone ? db()[phone] : null;
    const visits = c && Array.isArray(c.visits) ? c.visits : [];
    const last = visits[visits.length - 1];
    const ts = visitTs(last);
    if (!last || !ts) return { state: 'none' };
    const pct = last.offerPct !== undefined ? +last.offerPct : getLoyaltyPct();   // honour what the last bill promised
    if (!(pct > 0)) return { state: 'none' };
    const until = last.offerUntil ? +last.offerUntil : offerEndFor(ts);
    return { state: Date.now() <= until ? 'active' : 'expired', pct, until, from: fmtDate(ts), days: last.offerDays || getLoyaltyDays() };
}
function saveLoyaltyDays() {
    const n = parseInt($('admin-loyalty-days').value.trim(), 10);
    if (!Number.isFinite(n) || n < 1 || n > 365) return alert('Enter days between 1 and 365');
    localStorage.setItem('rzm_loyalty_days', String(n));
    updateLoyaltyUI(); flashSaved();
}
function saveLoyaltyPct() {
    const raw = $('admin-loyalty-pct').value.trim();
    const n = parseFloat(raw);
    if (raw === '' || !Number.isFinite(n) || n < 0 || n > 100) return alert('Enter a discount between 0 and 100');
    localStorage.setItem('rzm_loyalty_pct', String(n));
    updateLoyaltyUI(); flashSaved();
}
function updateLoyaltyUI() {
    const el = $('admin-loyalty-pct'); if (!el) return;
    const p = getLoyaltyPct();
    const dEl = $('admin-loyalty-days'); if (dEl && document.activeElement !== dEl) dEl.value = getLoyaltyDays();
    if (document.activeElement !== el) el.value = fmtPct(p);
    $('admin-loyalty-status').innerText = p > 0
        ? `Active: customers returning within ${getLoyaltyDays()} days get ${fmtPct(p)}% off. New invoices will show ${fmtPct(p)}%.`
        : 'Offer is OFF (0%). No discount and no offer line on invoices.';
}
const getUpiId = () => localStorage.getItem('rzm_upi_id') || CONFIG.upiId;
const getWhatsAppApiConfig = () => ({
    phoneNumberId: localStorage.getItem('rzm_wa_phone_id') || CONFIG.whatsappApiPhoneNumberId,
    accessToken: localStorage.getItem('rzm_wa_token') || CONFIG.whatsappApiAccessToken,
    apiVersion: CONFIG.whatsappApiVersion
});

// 1. Services grid (tap = select / unselect)
function renderServices() {
    $('services').innerHTML = services.map((c, ci) =>
        `<div class="cat">${esc(c.name)}</div>` +
        c.items.map((s, si) => `<button${cart.some(x => x.name === s.n) ? ' class="sel"' : ''} onclick="toggleService(this,${ci},${si})"><span class="service-name">${esc(s.n)}</span><span class="service-price">₹${priceFor(s)}</span></button>`).join('')
    ).join('') || '<p class="empty-msg" style="grid-column:1/-1">Add categories and services from Admin</p>';
}
function toggleService(btn, ci, si) {
    const s = services[ci].items[si], i = cart.findIndex(c => c.name === s.n);
    if (i >= 0) { cart.splice(i, 1); btn.classList.remove('sel'); }
    else { cart.push({ name: s.n, price: priceFor(s) }); btn.classList.add('sel'); }
    updateCartUI();
    $('checkout-section').classList.toggle('hidden', cart.length === 0);
}

// Normal / Prime price switch: re-prices the list AND anything already selected
function selectPricingTier(tier) {
    currentPricingTier = tier === 'Prime' ? 'Prime' : 'Normal';
    const isPrime = currentPricingTier === 'Prime';
    $('normal-price-view').classList.toggle('active', !isPrime);
    $('prime-price-view').classList.toggle('active', isPrime);
    $('normal-price-view').setAttribute('aria-pressed', String(!isPrime));
    $('prime-price-view').setAttribute('aria-pressed', String(isPrime));
    $('pricing-seg').dataset.tier = currentPricingTier;
    cart = cart.map(c => {
        for (const cat of services) for (const s of cat.items) if (s.n === c.name) return { name: c.name, price: priceFor(s) };
        return c;
    });
    renderServices();
    updateCartUI();
}

// WhatsApp logo button -> opens this app's own small WhatsApp panel: API
// setup (so the Admin doesn't need to touch it) + a local log of invoices
// sent through it. This is a personal, single-device app — not connected to
// Firebase or any server — so the log only ever shows what THIS browser
// itself sent, and whether that specific send succeeded or failed. Once a
// Phone Number ID + Access Token are saved here, every "Send Automatically"
// button elsewhere in the app starts working immediately — nothing else to
// wire up later.
function openWhatsAppChat() {
    updateWhatsAppPanel();
    $('whatsapp-panel-modal').classList.remove('hidden');
}
function getWhatsAppLog() {
    try { return JSON.parse(localStorage.getItem('rzm_wa_log') || '[]'); } catch (e) { return []; }
}
function logWhatsAppSend(entry) {
    const log = getWhatsAppLog();
    log.unshift({ ...entry, at: new Date().toLocaleString('en-IN') });
    localStorage.setItem('rzm_wa_log', JSON.stringify(log.slice(0, 50)));
    if (!$('whatsapp-panel-modal').classList.contains('hidden')) updateWhatsAppPanel();
}
function updateWhatsAppPanel() {
    const cfg = getWhatsAppApiConfig();
    const isSetUp = !!(cfg.phoneNumberId && cfg.accessToken);
    if ($('wa-phone-id')) $('wa-phone-id').value = cfg.phoneNumberId === CONFIG.whatsappApiPhoneNumberId ? '' : cfg.phoneNumberId;
    if ($('wa-token')) $('wa-token').value = cfg.accessToken === CONFIG.whatsappApiAccessToken ? '' : cfg.accessToken;
    if ($('wa-panel-status')) $('wa-panel-status').innerText = isSetUp
        ? '✅ Connected — "Send Automatically" buttons will send for real.'
        : '⚪ Not connected yet — "Send Automatically" buttons will just open manual WhatsApp until API details are saved here.';

    const log = getWhatsAppLog();
    $('wa-log-list').innerHTML = log.length
        ? log.map(e => `<div class="cust-row"><b>${esc(e.name || e.to)}</b> ${e.ok ? '<span style="color:#128c7e">✓ Sent</span>' : '<span class="danger">✕ Failed</span>'}<br><small>${esc(e.at)}${e.ok ? '' : ' — ' + esc(e.error || '')}</small></div>`).join('')
        : '<p class="empty-msg">No messages sent from here yet.</p>';
}
function savePanelWhatsAppApiSettings() {
    const phoneId = $('wa-phone-id').value.trim();
    const token = $('wa-token').value.trim();
    if (!phoneId || !token) return alert('Enter both Phone Number ID and Access Token');
    localStorage.setItem('rzm_wa_phone_id', phoneId);
    localStorage.setItem('rzm_wa_token', token);
    updateWhatsAppPanel();
}
// Opens WhatsApp's own "start a chat" interface (no number pre-filled) —
// same as tapping WhatsApp's own compose button — so you can type/search
// any contact and send a message directly, for anything outside an invoice.
function openExternalWhatsAppCompose() { window.open('https://api.whatsapp.com/send', '_blank'); }

// ===== ADMIN: category / service live edit =====
function openAdminLogin() { $('admin-pin').value = ''; $('admin-login').classList.remove('hidden'); $('admin-pin').focus(); }
function checkPin() {
    if ($('admin-pin').value !== CONFIG.adminPin) return alert('Incorrect PIN!');
    closeModal('admin-login'); renderAdmin(); $('admin-modal').classList.remove('hidden');
}
function closeAdmin() { closeModal('admin-modal'); cart = []; renderServices(); updateCartUI(); }
let adminSavedTimer = null;
function flashSaved() {
    const el = $('admin-saved'); if (!el) return;
    el.innerText = 'Saved ✓'; el.classList.add('flash');
    clearTimeout(adminSavedTimer);
    adminSavedTimer = setTimeout(() => { el.innerText = 'All changes saved ✓'; el.classList.remove('flash'); }, 1400);
}
// Every change is saved instantly; the list keeps its scroll position (no jump to the end/top)
function adminChanged(redraw, focusId) {
    saveServices(); renderServices(); flashSaved();
    if (redraw) renderAdmin();
    if (focusId && $(focusId)) $(focusId).focus({ preventScroll: true });
}
function addCat() {
    const n = $('new-cat').value.trim(); if (!n) return alert('Enter a category name');
    services.unshift({ name: n, items: [] }); $('new-cat').value = ''; adminChanged(true);
}
function editCat(ci, v) { if (v.trim()) { services[ci].name = v.trim(); adminChanged(false); } else adminChanged(true); }
function delCat(ci) { if (confirm(`Delete the "${services[ci].name}" category and all of its services?`)) { services.splice(ci, 1); adminChanged(true); } }
function addSvc(ci) {
    const n = $('ns-n' + ci).value.trim(), npRaw = $('ns-np' + ci).value, ppRaw = $('ns-pp' + ci).value;
    const normalPrice = +npRaw, primePrice = +ppRaw;
    if (!n || npRaw === '' || ppRaw === '' || !(normalPrice >= 0) || !(primePrice >= 0)) return alert('Enter service name, Normal Price and Prime Price');
    services[ci].items.push({ n, normalPrice, primePrice, p: normalPrice }); adminChanged(true, 'ns-n' + ci);
}
function editSvc(ci, si, k, v) {
    if (k === 'normalPrice') { services[ci].items[si].normalPrice = Math.max(0, +v || 0); services[ci].items[si].p = services[ci].items[si].normalPrice; }
    else if (k === 'primePrice') services[ci].items[si].primePrice = Math.max(0, +v || 0);
    else if (v.trim()) { services[ci].items[si].n = v.trim(); adminChanged(false); return; }
    else { adminChanged(true); return; }
    adminChanged(false);
}
function delSvc(ci, si) { services[ci].items.splice(si, 1); adminChanged(true); }
function saveUpiId() {
    const id = $('admin-upi-id').value.trim();
    if (!id) return alert('Enter UPI ID');
    localStorage.setItem('rzm_upi_id', id);
    $('admin-upi-status').innerText = 'UPI ID saved. Payment QR will use this ID.';
    updateUpiPreview();
}
function updateUpiPreview() {
    if ($('admin-upi-id')) $('admin-upi-id').value = getUpiId() === CONFIG.upiId ? '' : getUpiId();
}

function priceForAdmin(s, tier) { return tier === 'prime' ? (Number.isFinite(+s.primePrice) ? +s.primePrice : (+s.p || 0)) : (Number.isFinite(+s.normalPrice) ? +s.normalPrice : (+s.p || 0)); }
function renderAdmin() {
    updateUpiPreview();
    updateLoyaltyUI();
    const scroller = $('admin-modal').querySelector('.modal-box');
    const top = scroller ? scroller.scrollTop : 0;
    $('admin-list').innerHTML = services.map((c, ci) => `<div class="a-cat">
        <div class="a-head"><input class="field" value="${esc(c.name)}" onchange="editCat(${ci},this.value)"><button class="x" title="Delete category" onclick="delCat(${ci})">✕</button></div>` +
        c.items.map((s, si) => `<div class="a-row service-price-row"><input class="field" value="${esc(s.n)}" onchange="editSvc(${ci},${si},'n',this.value)"><input class="field p" type="number" min="0" value="${priceForAdmin(s,'normal')}" title="Normal Price" placeholder="Normal Price" onchange="editSvc(${ci},${si},'normalPrice',this.value)"><input class="field p" type="number" min="0" value="${priceForAdmin(s,'prime')}" title="Prime Price" placeholder="Prime Price" onchange="editSvc(${ci},${si},'primePrice',this.value)"><button class="x" onclick="delSvc(${ci},${si})">✕</button></div>`).join('') +
        `<div class="a-row service-price-row"><input class="field" id="ns-n${ci}" placeholder="New service" onkeydown="if(event.key==='Enter')addSvc(${ci})"><input class="field p" id="ns-np${ci}" type="number" min="0" placeholder="Normal Price"><input class="field p" id="ns-pp${ci}" type="number" min="0" placeholder="Prime Price" onkeydown="if(event.key==='Enter')addSvc(${ci})"><button class="add" onclick="addSvc(${ci})">＋</button></div></div>`
    ).join('');
    if (scroller) scroller.scrollTop = top;
}

// 2. Cart list + total
function updateCartUI() {
    totalAmount = cart.reduce((s, c) => s + c.price, 0);
    $('cart-items').innerHTML = cart.length
        ? cart.map(c => `<li class="cart-item"><span>${esc(c.name)}</span><span>₹${c.price}</span></li>`).join('')
        : '<li class="empty-msg">No services selected yet</li>';
    $('grand-total').innerText = '₹' + totalAmount;
    if ($('selected-count')) $('selected-count').innerText = cart.length;
}

// 3. Confirm services -> customer details
function openDetails() {
    if (!cart.length) return alert('Please select a service first!');
    $('details-modal').classList.remove('hidden');
    lookupCustomer('phone');
    $('c-phone').focus();
}

// Returning customer: type number (or name) -> saved customers show up, tap to select
function pickCustomer(phone) {
    const c = db()[phone];
    if (!c) return;
    $('c-phone').value = c.phone;
    $('c-name').value = c.name;
    lookupCustomer('phone');
}
function lookupCustomer(source) {
    const phone = $('c-phone').value.trim();
    const nameQ = $('c-name').value.trim().toLowerCase();
    const all = Object.values(db()).filter(c => c && c.name && c.phone);
    const box = $('cust-suggest'), status = $('cust-status');
    let matches = [];

    const exact = phone.length === 10 ? db()[phone] : null;
    $('c-name').readOnly = !!exact;   // registered number: name comes from the saved customer
    if (exact) {
        // saved customer found -> fill the name automatically
        if (source !== 'name') $('c-name').value = exact.name;
        const visits = Array.isArray(exact.visits) ? exact.visits.length : 0;
        const off = getReturnOffer(exact.phone);
        const offerLine = off.state === 'active'
            ? `<span class="cf-offer">🎁 ${fmtPct(off.pct)}% return discount will be applied (valid till ${fmtDate(off.until)})</span>`
            : off.state === 'expired' ? `<span class="cf-warn">Return offer expired on ${fmtDate(off.until)} — no discount this time. A new ${fmtPct(getLoyaltyPct())}% offer starts with this bill.</span>` : '';
        status.innerHTML = `<div class="cust-found"><span class="tick">!</span><div class="cf-main"><b>Already registered</b><br><b>${esc(exact.name)}</b> &bull; ${esc(exact.type === 'Prime' ? 'Prime' : 'Basic')} customer &bull; ${visits} visit(s)${offerLine}
            <span class="cf-actions"><button type="button" class="cf-btn" onclick="selectExistingCustomer('${esc(exact.phone)}')">Select &amp; Continue</button><button type="button" class="cf-btn alt" onclick="openEditCustomer('${esc(exact.phone)}','bill')">✎ Edit</button></span></div></div>`;
        box.classList.add('hidden'); box.innerHTML = '';
        return;
    }

    if (source === 'name' && nameQ.length >= 2) {
        matches = all.filter(c => c.name.toLowerCase().includes(nameQ));
    } else if (phone.length >= 2 && phone.length < 10) {
        matches = all.filter(c => c.phone.startsWith(phone));
    }
    matches = matches.slice(0, 6);
    box.innerHTML = matches.map(c => `<div class="sg-item" onclick="pickCustomer('${esc(c.phone)}')"><div><div class="sg-name">${esc(c.name)}</div><div class="sg-phone">+${esc(CONFIG.countryCode)} ${esc(c.phone)}</div></div><span class="sg-tag ${c.type === 'Prime' ? 'prime' : ''}">${esc((c.type === 'Prime') ? 'PRIME' : 'BASIC')}</span></div>`).join('');
    box.classList.toggle('hidden', !matches.length);
    status.innerHTML = phone.length === 10 ? '<div class="cust-new">New customer — enter the name. It will be saved after payment.</div>' : '';
}
// Select the registered customer: use their type's rates (Basic/Prime) and go to the bill
function selectExistingCustomer(phone) {
    const c = db()[phone]; if (!c) return;
    $('c-phone').value = c.phone; $('c-name').value = c.name;
    selectPricingTier(c.type === 'Prime' ? 'Prime' : 'Normal');
    showBill();
}
function closeModal(id) { $(id).classList.add('hidden'); }

// 4. Customer management
function updateSavedCount() { const el = $('saved-count'); if (el) el.innerText = Object.keys(db()).length; }
let selectedCustomerType = 'Basic';

let editingPhone = null, editOrigin = 'list';

function showCustomerError(msg) {
    const box = $('new-c-error');
    box.innerText = msg;
    box.classList.toggle('hidden', !msg);
}

function openAddCustomer() {
    editingPhone = null;
    $('edit-back-btn').classList.add('hidden');
    $('add-customer-title').innerText = 'Add Customer';
    $('save-customer-btn').innerText = 'Save Customer';
    $('new-c-name').value = '';
    $('new-c-phone').value = '';
    $('new-c-anniversary').value = '';
    $('new-c-message').value = '';
    showCustomerError('');
    selectCustomerType('Basic');
    $('add-customer-modal').classList.remove('hidden');
    $('new-c-name').focus();
}

function openEditCustomer(phone, from) {
    const c = db()[phone];
    if (!c) return;
    editingPhone = phone;
    editOrigin = from || 'list';
    $('edit-back-btn').classList.remove('hidden');
    $('add-customer-title').innerText = 'Edit Customer';
    $('save-customer-btn').innerText = 'Update Customer';
    $('new-c-name').value = c.name || '';
    $('new-c-phone').value = c.phone || phone;
    $('new-c-anniversary').value = c.anniversary || '';
    $('new-c-message').value = c.message || '';
    showCustomerError('');
    selectCustomerType(c.type === 'Prime' ? 'Prime' : 'Basic');
    closeModal('customer-detail-modal');
    if (from === 'bill') closeModal('details-modal');
    $('add-customer-modal').classList.remove('hidden');
    $('new-c-name').focus();
}

function editBack() {
    const p = editingPhone;
    editingPhone = null;
    closeModal('add-customer-modal');
    if (editOrigin === 'detail' && p) openCustomerDetail(p);
    if (editOrigin === 'bill') { editOrigin = 'list'; $('details-modal').classList.remove('hidden'); lookupCustomer('phone'); }
}

function selectCustomerType(type) {
    selectedCustomerType = type;
    $('basic-type-btn').classList.toggle('active', type === 'Basic');
    $('prime-type-btn').classList.toggle('active', type === 'Prime');
}

function saveNewCustomer() {
    const name = $('new-c-name').value.trim();
    const phone = $('new-c-phone').value.trim();
    const anniversary = $('new-c-anniversary').value;
    const message = $('new-c-message').value.trim();
    const isEdit = editingPhone !== null;

    if (!name) return showCustomerError('Please enter the customer name.');
    if (phone.length !== 10) return showCustomerError('WhatsApp number must be exactly 10 digits.');

    const d = db();
    if (d[phone] && phone !== editingPhone) {
        showCustomerError(`This number is already registered for "${d[phone].name}" (${d[phone].type === 'Prime' ? 'Prime' : 'Basic'}). `);
        const eb = $('new-c-error');
        eb.insertAdjacentHTML('beforeend', `<a href="#" style="color:#000;font-weight:800" onclick="event.preventDefault();openEditCustomer('${esc(phone)}','${editOrigin === 'bill' ? 'bill' : 'list'}')">Edit that customer</a>`);
        return;
    }

    const old = (isEdit && d[editingPhone]) ? d[editingPhone] : { visits: [] };
    if (isEdit && phone !== editingPhone) delete d[editingPhone];
    old.name = name;
    old.phone = phone;
    old.type = selectedCustomerType;
    old.anniversary = anniversary;
    old.message = message;
    old.visits = Array.isArray(old.visits) ? old.visits : [];
    old.updatedAt = new Date().toLocaleString('en-IN');
    d[phone] = old;
    localStorage.setItem('rzm_customers', JSON.stringify(d));

    editingPhone = null;
    closeModal('add-customer-modal');
    if (isEdit && editOrigin === 'bill') {   // back to billing; Basic<->Prime change applies to the rates here
        editOrigin = 'list';
        $('c-phone').value = old.phone; $('c-name').value = old.name;
        selectPricingTier(old.type === 'Prime' ? 'Prime' : 'Normal');
        $('details-modal').classList.remove('hidden');
        lookupCustomer('phone');
    }
    updateSavedCount();
    if (!$('customers-modal').classList.contains('hidden')) renderCustomers();
    showSaveSuccess(old, isEdit);
}

let saveToastTimer = null;
function showSaveSuccess(c, isEdit) {
    $('save-success-title').innerText = isEdit ? 'Customer Updated' : 'Customer Saved';
    $('save-success-sub').innerText = isEdit ? 'Details have been updated successfully.' : 'New customer has been added successfully.';
    $('save-success-chips').innerHTML =
        `<span class="save-chip">${esc(c.name)}</span>` +
        `<span class="save-chip ${c.type === 'Prime' ? 'prime' : ''}">${esc(c.type)}</span>` +
        `<span class="save-chip">+${esc(CONFIG.countryCode)} ${esc(c.phone)}</span>`;
    const bar = $('save-timer');
    bar.classList.remove('run'); void bar.offsetWidth; bar.classList.add('run');
    $('save-success-modal').classList.remove('hidden');
    clearTimeout(saveToastTimer);
    saveToastTimer = setTimeout(closeSaveSuccess, 2600);
}
function closeSaveSuccess() {
    clearTimeout(saveToastTimer);
    $('save-success-modal').classList.add('hidden');
}

