        doc.setFont(undefined,'normal'); doc.setFontSize(6.5); doc.text(`Visited again within ${CONFIG.loyaltyDays} days of last bill (${current.discountFrom})`,R,y,{align:'right'}); doc.setFontSize(8.5); y+=6;
