// 7a. WhatsApp Cloud API — AUTOMATIC sending (no manual tap-to-send).
// Needs Admin Panel > WhatsApp API set up first (Phone Number ID + Access
// Token from developers.facebook.com). Until then, sendWhatsAppAuto() below
// quietly falls back to the manual wa.me flow.
async function sendWhatsAppTextAPI(toPhone, message) {
    const cfg = getWhatsAppApiConfig();
    if (!cfg.phoneNumberId || !cfg.accessToken) throw new Error('WhatsApp API not configured');
    const to = CONFIG.countryCode + toPhone.replace(/\D/g, '');
    const res = await fetch(`https://graph.facebook.com/${cfg.apiVersion}/${cfg.phoneNumberId}/messages`, {
        method: 'POST',
        headers: { 'Authorization': `Bearer ${cfg.accessToken}`, 'Content-Type': 'application/json' },
        body: JSON.stringify({ messaging_product: 'whatsapp', to, type: 'text', text: { body: message } })
    });
    const data = await res.json();
    if (!res.ok) throw new Error((data.error && data.error.message) || 'WhatsApp API send failed');
    return data;
}

// 7b. Same idea but sends the actual invoice PDF as a WhatsApp document —
// Cloud API needs the file uploaded to Meta's servers first (returns a
// media_id), then that id is referenced in the document message.
async function sendWhatsAppPdfAPI(toPhone, caption) {
    const cfg = getWhatsAppApiConfig();
    if (!cfg.phoneNumberId || !cfg.accessToken) throw new Error('WhatsApp API not configured');
    const to = CONFIG.countryCode + toPhone.replace(/\D/g, '');

    const form = new FormData();
    form.append('messaging_product', 'whatsapp');
    form.append('file', new File([pdfDoc.output('blob')], pdfName(), { type: 'application/pdf' }));

    const uploadRes = await fetch(`https://graph.facebook.com/${cfg.apiVersion}/${cfg.phoneNumberId}/media`, {
        method: 'POST',
        headers: { 'Authorization': `Bearer ${cfg.accessToken}` },
        body: form
    });
    const uploadData = await uploadRes.json();
    if (!uploadRes.ok) throw new Error((uploadData.error && uploadData.error.message) || 'PDF upload to WhatsApp failed');

    const sendRes = await fetch(`https://graph.facebook.com/${cfg.apiVersion}/${cfg.phoneNumberId}/messages`, {
        method: 'POST',
        headers: { 'Authorization': `Bearer ${cfg.accessToken}`, 'Content-Type': 'application/json' },
        body: JSON.stringify({
            messaging_product: 'whatsapp', to, type: 'document',
            document: { id: uploadData.id, caption, filename: pdfName() }
        })
    });
    const sendData = await sendRes.json();
    if (!sendRes.ok) throw new Error((sendData.error && sendData.error.message) || 'WhatsApp API send failed');
    return sendData;
}

// 7c. The actual button handler — tries the API first (true "automatic",
// one tap, no WhatsApp app opening); if it's not configured yet, or Meta
// rejects it for any reason, falls back to the existing manual wa.me flow
// below so sending invoices never just stops working.
async function sendWhatsAppAuto(btn) {
    if (!current.phone) return alert('Customer WhatsApp number not available.');
    const msg = buildInvoiceMessage();
    const cfg = getWhatsAppApiConfig();
    if (!cfg.phoneNumberId || !cfg.accessToken) { sendWhatsApp(); return; }

    const originalText = btn ? btn.innerText : '';
    if (btn) { btn.innerText = 'Sending…'; btn.disabled = true; }
    try {
        await sendWhatsAppPdfAPI(current.phone, msg);
        logWhatsAppSend({ name: current.name, to: current.phone, ok: true });
        alert('Invoice sent automatically on WhatsApp to ' + current.name + '.');
    } catch (e) {
        console.error(e);
        logWhatsAppSend({ name: current.name, to: current.phone, ok: false, error: e.message });
        alert('Automatic send failed (' + e.message + '). Opening manual WhatsApp instead.');
        sendWhatsApp();
    } finally {
        if (btn) { btn.innerText = originalText; btn.disabled = false; }
    }
}

function buildInvoiceMessage() {
    return `Hello ${current.name}, thank you for visiting Relax Zone Makeover!
Invoice: ${current.inv}
Date: ${current.date} ${current.time}
Services: ${current.items.map(i=>i.name+' - ₹'+i.price).join(', ')}
${current.discountAmt > 0 ? `Subtotal: ₹${current.subtotal}\nReturn Visit Discount (${fmtPct(current.discountPct)}%): -₹${current.discountAmt}\n` : ''}Total: ₹${current.total}
Payment: ${current.paymentMethod}
${current.offerPct > 0 ? `Visit again by ${fmtDate(current.offerUntil)} and get ${fmtPct(current.offerPct)}% OFF on your total!\n` : ''}Relax Zone Makeover | 8093106151 | 1st Floor, Infront of Indian Oil Petroleum, Budharaja, Sambalpur - 768004`;
}

// 7. WhatsApp (manual): opens the customer's chat pre-filled with the
// invoice text; the PDF itself still needs to be attached by hand since
// wa.me links can't carry a file — used as the fallback when the API isn't
// set up, and still available as its own button for anyone who prefers it.
function sendWhatsApp() {
    if(!current.phone) return alert('Customer WhatsApp number not available.');
    window.open(`https://wa.me/${current.phone.replace(/\D/g,'')}?text=${encodeURIComponent(buildInvoiceMessage())}`, '_blank');
}

// 8. Saved customers list
function openCustomers() { renderCustomers(); $('customers-modal').classList.remove('hidden'); }
function renderCustomers() {
    const q = ($('c-search').value || '').trim().toLowerCase();
    const all = Object.values(db()).filter(c => c && c.name);
    const list = all.filter(c => !q || c.name.toLowerCase().includes(q) || String(c.phone || '').includes(q));

    const card = c => {
        const visits = Array.isArray(c.visits) ? c.visits : [];
        const spent = visits.reduce((s, v) => s + (+v.total || 0), 0);
        const last = visits[visits.length - 1];
        const lastTxt = last ? esc((last.items || []).map(i => i.name).join(', ')) : 'No service yet';
        const p = esc(c.phone);
        return `<div class="cust-row">
            <div class="cr-name">${esc(c.name)}</div>
            <div class="cr-phone">+${esc(CONFIG.countryCode)} ${p}</div>
            <div class="cr-meta">${visits.length} visit(s) &bull; ₹${spent} total<br>Last: ${lastTxt}</div>
            <div class="cust-actions">
                <button class="c-view" onclick="openCustomerDetail('${p}')">View Details</button>
                <button class="c-edit" onclick="openEditCustomer('${p}','list')">✎ Edit</button>
            </div>
        </div>`;
    };

    const fill = (type, listId, countId) => {
        const rows = list.filter(c => (c.type === 'Prime' ? 'Prime' : 'Basic') === type);
        $(countId).innerText = rows.length;
        $(listId).innerHTML = rows.length
            ? rows.map(card).join('')
            : (q
                ? `<div class="not-found"><b>Not found</b><span>No ${type} customer matches "${esc($('c-search').value.trim())}"</span></div>`
                : `<div class="not-found"><b>No ${type} customers yet</b><span>Use "Add Customer" to save one.</span></div>`);
    };
    fill('Basic', 'basic-list', 'basic-count');
    fill('Prime', 'prime-list', 'prime-count');
}

